assert CONFORMAL_COMPONENTS[0][2] == MOVE

# Exact honest-affine collision.  Coefficients sum to zero, and every physical,
# glue, DROP, and nonlocal pair coordinate cancels.
AFFINE_COMBINATION = tuple(
    a - b - c + d
    for a, b, c, d in zip(
